import networkx as nx

def quota_forest(rng, size, prefix):
    nodes = []
    ids = []
    for i in range(size):
        nid = '%s%d' % (prefix, i)
        parent = None if i == 0 or rng.random() < 0.3 else rng.choice(ids)
        nodes.append({'id': nid, 'parent': parent, 'capacity': rng.choice([0, 1, 2, 3, 5, 4096])})
        ids.append(nid)
    # avoid long chains
    for i in range(34, size):
        nodes[i]['parent'] = rng.choice(ids[:min(i, 32)])
    return nodes

