def _fix(nodes):
    ids = [n['id'] for n in nodes]
    out = []
    for n in nodes:
        if n['id'] in ids[:ids.index(n['id'])]:
            continue
        if n['parent'] is not None and n['parent'] not in ids:
            n = dict(n, parent=None)
        out.append(n)
    # break cycles and over-long paths
    changed = True
    guard = 0
    while changed and guard < 50:
        changed = False
        guard += 1
        table = {n['id']: n for n in out}
        for n in out:
            path = []
            at = n['id']
            while at is not None:
                if at in path or len(path) > 32:
                    n['parent'] = None
                    changed = True
                    break
                path.append(at)
                at = table[at]['parent'] if at in table else None
    return out

def brute(job, out):
    """Independently compute the optimum with networkx."""
    active = {row['id']: row['active'] for row in out['active_requests']}
    leases = {l['id']: l for l in job['leases']}
    rnodes = {n['id']: n for n in job['request_quotas']}
    onodes = {n['id']: n for n in job['offer_quotas']}
    requests = {r['id']: r for r in job['requests']}
    edges = []
    for o in job['offers']:
        for rid in o['requests']:
            r = requests[rid]
            if not active.get(rid):
                continue
            if r['service'] != o['service']:
                continue
            if not (r['at'] <= o['time'] < leases[r['lease']]['end']):
                continue
            import ipaddress
            if ipaddress.IPv6Address(r['target']) not in ipaddress.IPv6Network(o['prefix']):
                continue
            edges.append((rid, o['id'], o['cost']))
    G = nx.DiGraph()
    G.add_node('S'); G.add_node('T')
    for rid in {e[0] for e in edges}:
        G.add_edge('S', 'R' + rid, capacity=1, weight=0)
        g = requests[rid]['group']
        prev = 'R' + rid
        seen = set()
        while g is not None and g in rnodes and g not in seen:
            seen.add(g)
            G.add_edge(prev, 'RQ' + g, capacity=rnodes[g]['capacity'], weight=0)
            prev = 'RQ' + g
            g = rnodes[g]['parent']
        if prev != 'R' + rid:
            G.add_edge(prev, 'J', capacity=10 ** 9, weight=0) if 'J' not in G else None
            G.add_edge(prev, 'J', capacity=10 ** 9, weight=0)
    if 'J' in G:
        G.add_edge('J', 'T', capacity=10 ** 9, weight=0)
    for o in job['offers']:
        oid = o['id']
        if not any(e[1] == oid for e in edges):
            continue
        g = o['group']
        prev = 'O' + oid
        G.add_edge(prev, 'OQ' + g, capacity=o['capacity'], weight=0)
        cur = 'OQ' + g
        seen = set()
        while True:
            if cur in seen:
                break
            seen.add(cur)
            p = onodes.get(cur, {}).get('parent') if cur in onodes else None
            if p is None:
                G.add_edge(cur, 'T', capacity=onodes[cur]['capacity'] if cur in onodes else 10 ** 9, weight=0)
                break
            G.add_edge(cur, 'OQ' + p, capacity=onodes[cur]['capacity'], weight=0)
            cur = 'OQ' + p
    for rid, oid, cost in edges:
        G.add_edge('R' + rid, 'O' + oid, capacity=1, weight=cost)
    if not edges:
        return 0, 0
    value = nx.maximum_flow_value(G, 'S', 'T')
    if value == 0:
        return 0, 0
    H = nx.DiGraph(G)
    H.add_node('S', demand=-value); H.add_node('T', demand=value)
    cost, _ = nx.network_simplex(H)
    return value, cost

def feasible(job, out):
    leases = {l['id']: l for l in job['leases']}
    requests = {r['id']: r for r in job['requests']}
    offers = {o['id']: o for o in job['offers']}
    rnodes = {n['id']: n for n in job['request_quotas']}
    onodes = {n['id']: n for n in job['offer_quotas']}
    active = {row['id']: row['active'] for row in out['active_requests']}
    import ipaddress
    rows = out['plan']['assignments']
    ids = [r['request'] for r in rows]
    if ids != sorted(ids):
        return 'not sorted'
    if len(set(ids)) != len(ids):
        return 'duplicate request'
    used = {}
    rq_use = {}
    oq_use = {}
    total = 0
    for row in rows:
        rid, oid = row['request'], row['offer']
        if not active.get(rid):
            return 'inactive request'
        r, o = requests[rid], offers[oid]
        if r['service'] != o['service']:
            return 'service mismatch'
        if not (r['at'] <= o['time'] < leases[r['lease']]['end']):
            return 'time window'
        if ipaddress.IPv6Address(r['target']) not in ipaddress.IPv6Network(o['prefix']):
            return 'prefix'
        if oid not in o['requests']:
            return 'not listed'
        used[oid] = used.get(oid, 0) + 1
        total += o['cost']
        g = r['group']
        while g is not None and g in rnodes:
            rq_use[g] = rq_use.get(g, 0) + 1
            g = rnodes[g]['parent']
        g = o['group']
        while g is not None and g in onodes:
            oq_use[g] = oq_use.get(g, 0) + 1
            g = onodes[g]['parent']
    for oid, count in used.items():
        if count > offers[oid]['capacity']:
            return 'offer capacity'
    for g, count in rq_use.items():
        if count > rnodes[g]['capacity']:
            return 'request quota %s' % g
    for g, count in oq_use.items():
        if count > onodes[g]['capacity']:
            return 'offer quota %s' % g
    if total != out['plan']['cost']:
        return 'cost mismatch %d != %d' % (total, out['plan']['cost'])
    if len(rows) != out['plan']['resolved']:
        return 'resolved mismatch'
    return None

