    value, cost = brute(job, out)
    if (value, cost) != (out['plan']['resolved'], out['plan']['cost']):
        print('trial', trial, 'OPTIMUM', (value, cost), 'got', (out['plan']['resolved'], out['plan']['cost']))
        bad += 1
print('bad', bad, 'of', trial + 1)
